import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import jsPDF from 'jspdf';
import { Invoice, InvoiceItem } from '../../models/invoice';
import { OrderService } from '../../services/order-service';
import { OrderDispatchList } from '../order-dispatch-list/order-dispatch-list';
import { party } from '../party/party';
import { InvoiceService } from '../../services/invoice-service';
import { PartyService } from '../../services/party-service';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
declare var bootstrap: any; 
@Component({
  selector: 'app-pending-orders',
  imports: [FormsModule, CommonModule, RouterLink],
  templateUrl: './pending-orders.html',
  styleUrl: './pending-orders.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PendingOrders {
  showConfirm = false;
  selectedInvoiceId: number | null = null;
order: OrderDispatchList[] = [];
 invoice: Invoice[] = [];
 parties: party[] = [];
  searchTerm = '';

  constructor(private userService: OrderService,  private cd: ChangeDetectorRef, private InvoiceService: InvoiceService, private PartyService: PartyService) {}

  ngOnInit() {
    this.userService.getOrdersByStatus(1).subscribe(data => {
  this.order = data.map(i => ({
    id: i.id,
    invoiceId: i.id,
    invoiceNo: i.invoiceNo,
    customerName: i.customerName,
    customerPhone: i.customerPhone,
    customerEmail: i.customerEmail,
    orderDate: i.orderDate
  }));
  this.cd.markForCheck();
});
    console.log("Users from backend:", this.order);

  // 2️⃣ Fetch Parties
this.PartyService.getParties().subscribe({
  next: (data) => {
    this.parties = data;
    console.log('Parties fetched:', this.parties);
  },
  error: (err) => {
    console.error('Failed to fetch parties:', err);
  }
});
  }

 openConfirmModal(invoiceId: number) {
    this.selectedInvoiceId = invoiceId;
    this.showConfirm = true;
    console.log("button is clicked")
  }

  closeConfirm() {
    this.showConfirm = false;
    this.selectedInvoiceId = null;
  }

  confirmCompleteOrder() {
    if (!this.selectedInvoiceId) return;

    console.log('Completing order for invoice ID:', this.selectedInvoiceId);
   
  this.InvoiceService.updateStatus(this.selectedInvoiceId, 2).subscribe({
    next: (res) => {
      console.log("Status updated:", res);
      this.ngOnInit(); // reload data
    },
    error: (err) => console.error("Failed to update status:", err)
  });
    this.closeConfirm();
  }


  filteredUsers() {
    const term = this.searchTerm.toLowerCase();
    return this.order.filter(u =>
      u.invoiceNo.toString().includes(term) ||
      u.customerName.toLowerCase().includes(term) ||
      u.customerPhone.toString().includes(term) ||
      u.customerEmail.toLowerCase().includes(term) ||
      u.orderDate.toLowerCase().includes(term)
    );
  }

}
